/// <summary>
/// Extension class for enabling Transfer Order navigation from Arrival Overview
/// by bypassing XDS in jumpRef.
/// </summary>
[ExtensionOf(formDataFieldStr(WMSArrivalOverview, WMSArrivalOverviewTmp, InventTransRefId))]
final class METWMSArrivalOverview_WMSArrivalOverviewTmpDS_InventTransferId_Extension
{
}

Method.Source:
/// <summary>
/// Overrides jumpRef to allow navigation to the Transfer Order
/// when XDS would normally block access.
/// </summary>
public void jumpRef()
{
    unchecked(Uncheck::XDS)
    {
        next jumpRef();
    }
}
